/* Character-owned feats outside the printed feat catalog. */
let customFeatDraft=null,customFeatReturnPicker=false;
function psiUpgrade(entry,index){const text=entry?.rows[index]?.[6]?.trim();if(!text)return null;const first=entry.rows.findIndex(r=>r[6]?.trim()===text),kind=/^эпическ/i.test(text)?'epic':'simple';return {id:'psi-feat:'+entry.id+':'+first,title:entry.title+' · '+(kind==='epic'?'эпический фит':'стандартный фит'),text,kind,category:kind==='epic'?'Эпик':'Простые фиты',extraKind:'psi',abilityId:entry.id,row:first};}
function psiUpgradeCatalog(){return PSI_CATALOG.flatMap(e=>e.rows.map((r,i)=>psiUpgrade(e,i)).filter(Boolean)).filter((e,i,all)=>all.findIndex(x=>x.id===e.id)===i);}
function psiPurchasedFeats(){const ids=new Set(Array.isArray(state.play.psiFeats)?state.play.psiFeats:[]);for(const c of state.play.psiCards||[]){const e=psiEntry(c.abilityId);if(e)for(const i of c.feats||[]){const f=psiUpgrade(e,i);if(f)ids.add(f.id);}}return psiUpgradeCatalog().filter(e=>ids.has(e.id));}
function customFeatEntries(){return (state.play.customFeats||[]).map(f=>({...f,category:f.kind==='epic'?'Эпик':'Простые фиты',extraKind:'custom'}));}
function migrateExtraFeats(){
 const ids=new Set();state.play.customFeats=(Array.isArray(state.play.customFeats)?state.play.customFeats:[]).filter(f=>f&&typeof f.id==='string'&&f.id.startsWith('custom-feat:')&&typeof f.title==='string'&&f.title.trim()&&typeof f.text==='string'&&['simple','penalty','epic'].includes(f.kind)&&!ids.has(f.id)&&ids.add(f.id)).map(f=>({id:f.id,title:f.title.trim().slice(0,160),text:f.text.slice(0,6000),kind:f.kind}));
 const valid=new Set(psiUpgradeCatalog().map(f=>f.id));state.play.psiFeats=[...new Set(Array.isArray(state.play.psiFeats)?state.play.psiFeats:[])].filter(id=>valid.has(id));
}
function removePsiFeat(id){state.play.psiFeats=(state.play.psiFeats||[]).filter(x=>x!==id);for(const c of state.play.psiCards||[]){const e=psiEntry(c.abilityId);if(e)c.feats=c.feats.filter(i=>psiUpgrade(e,i)?.id!==id);}}
function togglePsiUpgrade(id){if(!psiUpgradeCatalog().some(e=>e.id===id))throw Error('Пси-фит не найден.');if(psiPurchasedFeats().some(e=>e.id===id))removePsiFeat(id);else state.play.psiFeats.push(id);}
function storeCustomFeat(draft){const title=String(draft.title||'').trim(),text=String(draft.text||'').trim();if(!title||title.length>160)throw Error('Укажите название до 160 символов.');if(text.length>6000)throw Error('Описание: до 6000 символов.');if(!['simple','penalty','epic'].includes(draft.kind))throw Error('Выберите тип фита.');const f={id:draft.id||'custom-feat:'+crypto.randomUUID(),title,text,kind:draft.kind},index=state.play.customFeats.findIndex(x=>x.id===f.id);if(index<0)state.play.customFeats.push(f);else state.play.customFeats[index]=f;return f;}
const beforeExtraSelectedFeats=selectedFeats,beforeExtraFeatKind=featKind;
selectedFeats=function(){return [...beforeExtraSelectedFeats(),...psiPurchasedFeats(),...customFeatEntries()];};
featKind=function(e){return e.extraKind?e.kind:beforeExtraFeatKind(e);};
const beforeExtraMigrateChoices=migrateFeatChoices;
migrateFeatChoices=function(){state.play.featChoices??={};for(const e of selectedFeats().filter(e=>e.extraKind))state.play.featChoices[e.id]=[e.kind];beforeExtraMigrateChoices();};
function extraFeatControls(e){return `${e.extraKind==='custom'?`<button data-extra-feat-edit="${e.id}">Изменить</button>`:''}<button data-extra-feat-remove="${e.id}">Убрать фит</button>`;}
function extraFeatMarkup(e){return `<details class="extra-feat"><summary>${esc(e.title)} <small>${e.kind==='epic'?'эпический':e.kind==='penalty'?'со штрафом':'простой'}${e.extraKind==='custom'?' · свой':''}</small></summary><p class="rule-text">${esc(e.text)}</p><div class="play-shortcuts">${extraFeatControls(e)}</div></details>`;}
const beforeExtraSummaryFeats=renderSummaryFeats;
renderSummaryFeats=function(){const extras=selectedFeats().filter(e=>e.extraKind);let html=beforeExtraSummaryFeats();for(const e of extras)html=html.replace(`<button data-effect-source="${e.id}">Настроить бонусы</button>`,extraFeatControls(e));return html.replace('<button data-workflow="open-feats">+ Выбрать</button>','<button data-workflow="open-feats">+ Выбрать</button><button data-extra-feat-action="new">+ Свой фит</button>');};
const beforeExtraFeatResults=renderFeatPickerResults,beforeExtraFeatPicker=renderFeatPicker,beforeExtraAbilities=renderAbilities;
renderFeatPickerResults=function(){const extras=selectedFeats().filter(e=>e.extraKind&&(featPickerCategory==='Все'||e.category===featPickerCategory)&&(e.title+' '+e.text).toLowerCase().includes(featPickerQuery.toLowerCase())).map(extraFeatMarkup).join('');return beforeExtraFeatResults().replace(extras?'<p>Ничего не найдено.</p>':'','')+extras;};
renderFeatPicker=function(){return beforeExtraFeatPicker().replace('<div id="feat-picker-balance">','<button class="new-custom-feat-button" data-extra-feat-action="new">+ Создать свой фит</button><div id="feat-picker-balance">');};
renderAbilities=function(){const extras=selectedFeats().filter(e=>e.extraKind);return beforeExtraAbilities()+`<section class="panel extra-feats-panel">${playHeading('ФИТЫ ПЕРСОНАЖА','Пси-фиты и свои фиты','<button data-extra-feat-action="new">+ Свой фит</button>')}${renderFeatBalances()}${extras.map(extraFeatMarkup).join('')||'<p class="empty-state">Выберите улучшения пси-способностей или создайте свой фит.</p>'}</section>`;};
const beforeExtraPsiCard=psiCard,beforeExtraCardChoices=psiCardFieldChoices,beforeExtraPsiPage=renderPsiPage;
renderPsiPage=function(){return beforeExtraPsiPage().replace('<div class="psi-cards">','<div id="psi-feat-balance">'+renderFeatBalances()+'</div><div class="psi-cards">');};
psiCard=function(entry){const selected=new Set(psiPurchasedFeats().map(e=>e.id)),upgrades=psiUpgradeCatalog().filter(e=>e.abilityId===entry.id);return beforeExtraPsiCard(entry).replace('</article>',`<details class="psi-feat-choices"><summary>Фиты способности</summary>${upgrades.map(e=>`<label class="check-row"><input type="checkbox" data-psi-upgrade="${e.id}" ${selected.has(e.id)?'checked':''}><span>${esc(e.text)}<small>1 ${e.kind==='epic'?'эпическое':'простое'} очко фитов</small></span></label>`).join('')}</details></article>`);};
psiCardFieldChoices=function(){return '<div class="psi-feat-cost-note">'+renderFeatBalances()+'<small>Выбранные фиты списываются при сохранении, без повторной оплаты за другие карточки.</small></div>'+beforeExtraCardChoices();};
function renderCustomFeatDialog(){const d=customFeatDraft;return `<dialog id="custom-feat-dialog" class="formula-dialog" aria-labelledby="custom-feat-title"><div class="toolbar"><h2 id="custom-feat-title">${d.id?'Изменить свой фит':'Создать свой фит'}</h2><button data-extra-feat-action="cancel" aria-label="Закрыть свой фит">×</button></div><label>Название фита<input id="custom-feat-name" maxlength="160" value="${esc(d.title)}"></label><label>Тип фита<select id="custom-feat-kind">${[['simple','Простой'],['penalty','Со штрафом'],['epic','Эпический']].map(([key,label])=>`<option value="${key}" ${d.kind===key?'selected':''}>${label}</option>`).join('')}</select></label><label>Описание и эффекты<textarea id="custom-feat-text" rows="6" maxlength="6000">${esc(d.text)}</textarea></label><p id="custom-feat-error" class="formula-error" role="status"></p><div class="dialog-actions"><button data-extra-feat-action="cancel">Отмена</button><button data-extra-feat-action="save">Сохранить фит</button></div></dialog>`;}
function closeCustomFeat(){customFeatDraft=null;featPickerOpen=customFeatReturnPicker;customFeatReturnPicker=false;document.querySelector('#custom-feat-dialog')?.close();render();}
const beforeExtraSave=save,beforeExtraRender=render;
save=function(){migrateExtraFeats();beforeExtraSave();};
render=function(){migrateExtraFeats();beforeExtraRender();if(libraryHome){customFeatDraft=null;return;}if(customFeatDraft){document.querySelector('#view').insertAdjacentHTML('beforeend',renderCustomFeatDialog());document.querySelector('#custom-feat-dialog').showModal();}};
document.addEventListener('click',event=>{const b=event.target.closest('[data-extra-feat-action],[data-extra-feat-edit],[data-extra-feat-remove]');if(!b)return;event.preventDefault();event.stopImmediatePropagation();const d=b.dataset;
 if(d.extraFeatAction==='new'||d.extraFeatEdit){const f=state.play.customFeats.find(f=>f.id===d.extraFeatEdit);customFeatDraft=f?structuredClone(f):{title:'',text:'',kind:'simple'};customFeatReturnPicker=featPickerOpen;featPickerOpen=false;render();return;}
 if(d.extraFeatAction==='cancel')return closeCustomFeat();
 if(d.extraFeatAction==='save'){try{storeCustomFeat({...customFeatDraft,title:document.querySelector('#custom-feat-name').value,text:document.querySelector('#custom-feat-text').value,kind:document.querySelector('#custom-feat-kind').value});save();closeCustomFeat();}catch(error){document.querySelector('#custom-feat-error').textContent=error.message;}return;}
 if(d.extraFeatRemove){if(d.extraFeatRemove.startsWith('psi-feat:'))removePsiFeat(d.extraFeatRemove);else state.play.customFeats=state.play.customFeats.filter(f=>f.id!==d.extraFeatRemove);save();render();}
},true);
document.addEventListener('change',event=>{const id=event.target.dataset.psiUpgrade;if(!id)return;event.stopImmediatePropagation();togglePsiUpgrade(id);save();const selected=new Set(psiPurchasedFeats().map(e=>e.id));document.querySelectorAll('[data-psi-upgrade]').forEach(el=>el.checked=selected.has(el.dataset.psiUpgrade));const balance=document.querySelector('#psi-feat-balance');if(balance)balance.innerHTML=renderFeatBalances();},true);
document.addEventListener('cancel',event=>{if(event.target.id==='custom-feat-dialog'){event.preventDefault();closeCustomFeat();}},true);
render();
